def __setitem__(self, key, value):
    value = extract_array(value, extract_numpy=True)

    if not lib.is_scalar(key) and is_list_like(key):
        key = np.asarray(key)

    if not lib.is_scalar(value):
        value = np.asarray(value)

    values = self._ndarray

    # Check if the key and value shapes match for assignment
    if np.ndim(values) != np.ndim(value) and np.numel(key) != np.ndim(value):
        raise ValueError("Incompatible shapes for key and value assignment.")

    t = np.result_type(value, values)

    if t != self._ndarray.dtype:
        values = values.astype(t, casting="safe")
        self._dtype = PandasDtype(t)

    # Ensure that assignment is performed correctly
    if np.shape(key) > 0:
        values[key] = value
    else:
        raise ValueError("Key must not be an empty index.")

    self._ndarray = values
