def __setitem__(self, key, value):
    value = extract_array(value, extract_numpy=True)

    if not lib.is_scalar(key) and is_list_like(key):
        key = np.asarray(key)

    if isinstance(value, str):
        value = np.array(value, dtype=np.object)  # Ensures string values are treated correctly

    if not lib.is_scalar(value):
        value = np.asarray(value)

    values = self._ndarray

    # Handling the expected types more carefully
    t = np.result_type(value, values)

    if t != self._ndarray.dtype:
        if self._ndarray.size != value.size and not (len(key) == 1 and isinstance(value, np.ndarray)):
            raise ValueError("Value must match the shape of the target array.")
        values = values.astype(t, casting="safe")

    values[key] = value  # Direct assignment, should now work correctly

    self._dtype = PandasDtype(t)
    self._ndarray = values
```
